#pragma once
#include "board.h"
namespace ataxx {
struct WideWeights {
    std::int16_t table[46][68715];
    std::uint32_t map[531441];
    u64 rows[128][3];
};
inline const WideWeights& wideWeights() {
    static const WideWeights weights = [] {
        WideWeights result;
        std::int16_t packed[6][68715];
        const char* data = "";
        const char* alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        int digits[128]{};
        for (int i = 0; i < 64; ++i) digits[int(alphabet[i])] = i;
        auto* out = reinterpret_cast<unsigned char*>(packed);
        for (unsigned i = 0; i < sizeof(packed) / 3; ++i) {
            unsigned value = (digits[int(data[4*i])] << 18) | (digits[int(data[4*i+1])] << 12) | (digits[int(data[4*i+2])] << 6) | digits[int(data[4*i+3])];
            out[3*i] = value >> 16;
            out[3*i+1] = value >> 8;
            out[3*i+2] = value;
        }
        const int cells[12] = {0,2,4,6,8,10,14,16,18,20,22,24};
        int power[12], inverse[25]{}, transformed[8][2][729];
        power[0] = 1;
        for (int i = 1; i < 12; ++i) power[i] = 3 * power[i-1];
        for (int i = 0; i < 12; ++i) inverse[cells[i]] = i;
        for (int t = 0; t < 8; ++t) for (int half = 0; half < 2; ++half) for (int code = 0; code < 729; ++code) {
            int value = code, mapped = 0;
            for (int i = 0; i < 6; ++i, value /= 3) {
                int cell = cells[6 * half + i], x = cell % 5, y = cell / 5;
                if (t & 1) x = 4 - x;
                if (t & 2) y = 4 - y;
                if (t & 4) std::swap(x, y);
                mapped += (value % 3) * power[inverse[5*y+x]];
            }
            transformed[t][half][code] = mapped;
        }
        int count = 0;
        for (int code = 0; code < 531441; ++code) {
            int canonical = code;
            for (int t = 1; t < 8; ++t) canonical = std::min(canonical, transformed[t][0][code % 729] + transformed[t][1][code / 729]);
            result.map[code] = canonical == code ? count++ : result.map[canonical];
        }
        for (int row = 0; row < 128; ++row) for (int kind = 0; kind < 3; ++kind) {
            u64 packedRow = 0;
            for (int start = 0; start < 3; ++start) {
                int a = kind == 1 ? 1 : 0, b = kind == 0 ? 2 : kind == 1 ? 3 : 4;
                int code = ((row >> (start+a)) & 1) + 3 * ((row >> (start+b)) & 1);
                if (kind == 0) code += 9 * ((row >> (start+4)) & 1);
                packedRow |= u64(code) << (20 * start);
            }
            result.rows[row][kind] = packedRow;
        }
        const int knots[6] = {0,2,5,10,20,45};
        for (int e = 0; e <= 45; ++e) {
            int lo = 0;
            while (lo < 4 && knots[lo+1] <= e) ++lo;
            int den = knots[lo+1]-knots[lo], num = e-knots[lo];
            for (int code = 0; code < 68715; ++code) {
                int value = (den-num) * packed[lo][code] + num * packed[lo+1][code];
                result.table[e][code] = 2 * (value >= 0 ? (value + den/2) / den : -((-value + den/2) / den));
            }
        }
        return result;
    }();
    return weights;
}
}
